\label{lem:rank-one}
Let $A$ be the adjacency matrix of a graph in $\mathscr G_3(\theta_0,\theta_1,\theta_2)$.  
There is a positive $\theta_0$-eigenvector $\bm\alpha$ such that
\begin{equation}\label{eqn:3ev}
    A^2-(\theta_1+\theta_2)A+\theta_1\theta_2I
       =\bm\alpha\bm\alpha^ 
  {\mathpalette\@transpose{}} 
.
\end{equation}
For each vertex $\mathsf x$ of degree $d_{\mathsf x}$, we have $\alpha_{\mathsf x}^2=d_{\mathsf x}+\theta_1\theta_2$.
Moreover, $\theta_1\geqslant0$ and  $\theta_2\leqslant-\sqrt2$.

\label{thm:bireg}
    Let $\Gamma \in \mathscr{G}_3(\theta_0,\theta_1,\theta_2)$ be a non-bipartite biregular graph with degrees $k_1$ and $k_2$, and let $Q=Q_{\mathfrak D(\Gamma)}(\Gamma)$.  
    Then
	\begin{enumerate}
		\item[\textup{(i)}] All eigenvalues of $\Gamma$ are integers.
        \item[\textup{(ii)}] The quotient matrix $Q$ has eigenvalues $\theta_0$ and $\theta$, where $\theta \in \{\theta_1,\theta_2\}$.
		\item[\textup{(iii)}] Letting $\{\theta, \theta'\} = \{\theta_1, \theta_2\}$, we have $\alpha_1\alpha_2 = -\theta(\theta' +1)$.
        \item[\textup{(iv)}] If either part of the degree partition induces an empty subgraph, then $\theta = \theta_2$.
  \end{enumerate}

\label{thm:2-des}
Let $\Gamma\in\mathscr G_3(\theta_0,\theta_1,\theta_2)$ be connected and biregular, with degree partition $\{V_1,V_2\}$, adjacency matrix $\left[\begin{smallmatrix}A_1&B\\B^ 
  {\mathpalette\@transpose{}} 
&A_2\end{smallmatrix}\right]$, and degree-partition quotient matrix $\left[\begin{smallmatrix}k_{11}&k_{12}\\k_{21}&k_{22}\end{smallmatrix}\right]$.
Suppose that $n_1=mn$ for integers $m,n\geqslant2$, and that $\Gamma[V_1]=\overline{mK_n}$ or $\Gamma[V_1]=mK_n$.
Then $B$ is the incidence matrix of a GDD $\mathcal D$ with parameters $(n_1,n_2;k_{12},k_{21};\lambda_1,\lambda_2;m,n)$, where
\begin{equation}
\label{eqn:l1l2}
    (\lambda_1,\lambda_2)=
\begin{cases}
\bigl(k_{12}+\theta_1\theta_2,
      k_{12}+(\theta_1+1)(\theta_2+1)-1+n\bigr),
   &\text{if $\Gamma[V_1]=\overline{mK_n}$},\\[3pt]
\bigl(k_{12}+(\theta_1+1)(\theta_2+1),
      k_{11}+k_{12}+\theta_1\theta_2\bigr),
   &\text{if $\Gamma[V_1]=mK_n$}.
\end{cases}
\end{equation}
If $\mathcal D$ is semiregular, then both of the following conclusions hold:
\[
n=
\begin{cases}
-\theta_2,&\text{if $\Gamma[V_1]=\overline{mK_n}$},\\
\theta_1+1,&\text{if $\Gamma[V_1]=mK_n$},
\end{cases}
\]
and
\[
\operatorname{Spec}(A_2)\subseteq
\begin{cases}
\{k_{22},\theta_1,-n,\theta_1-n\},
    &\text{if $\Gamma[V_1]=\overline{mK_n}$},\\
\{k_{22},n-1,\theta_2,n+\theta_2\},
    &\text{if $\Gamma[V_1]=mK_n$}.
\end{cases}
\]

\label{thm:gdd-to-3ev}
Let $B$ be the incidence matrix of a semiregular group divisible design $\mathcal D$ with parameters $(v,b;r,k;\lambda_1,\lambda_2;m,n)$, where $m,n\geqslant2$.
Suppose there is a $k_\Gamma$-regular graph $\Gamma$ on $b$ vertices such that
\begin{align}
    B A(\Gamma) &= (\lambda_2-\lambda_1-n)B
        + \frac{k}{v}(k_\Gamma+\lambda_1-\lambda_2+n)J,
        \label{eqn:aux-mixed}\\[3pt]
         A(\Gamma)^2-(\lambda_2-\lambda_1-n)A(\Gamma)+B^ 
  {\mathpalette\@transpose{}} 
 B
        &=\frac{1}{b}\big((k_\Gamma+\lambda_1-\lambda_2)(k_\Gamma+n)+rk\big)J
                     +n(\lambda_2-\lambda_1)I,
        \label{eqn:aux-block}\\[3pt]
        \left(\frac{k(m-1)}{m}
                 +\frac{k}{v}(k_\Gamma+\lambda_1-\lambda_2+n)\right)^2
        &=\frac{v-n+\lambda_1}{b}
                     \big((k_\Gamma+\lambda_1-\lambda_2)(k_\Gamma+n)+rk\big).
        \label{eqn:aux-scalar}
\end{align}
Then the block matrix $\left [ \begin{smallmatrix} X_{\mathcal D} & B \\ B^ 
  {\mathpalette\@transpose{}} 
 & A(\Gamma) \end{smallmatrix} \right ]$ is the adjacency matrix of a connected graph in
\[
\mathscr{G}_3 \left (\frac{v - n + k_\Gamma + \sqrt{(v - n - k_\Gamma)^2 + 4rk}}{2}, \lambda_2 - \lambda_1, -n \right ),
\]
which is biregular if and only if $v-n+r\ne k_\Gamma+k$; otherwise, it is regular.

\label{lem:auxSpec}
    Let $\mathcal D$ be a semiregular group divisible design with parameters $(v,b; r,k; \lambda_1, \lambda_2; m, n)$.
    Suppose $\Gamma$ is an auxiliary graph of $\mathcal D$.
    Then 
    \[
    \operatorname{Spec}(A(\Gamma)) = \left \{ [k_\Gamma]^1, [\lambda_2-\lambda_1 - n]^{m(n-1)}, [\lambda_2-\lambda_1]^x, [-n]^y  \right \},
    \]
    where $x = \frac{n(b-1) - k_{\Gamma} - m(\lambda_2 - \lambda_1)(n-1)}{\lambda_2 - \lambda_1 + n}$ and $y = \frac{(\lambda_2 - \lambda_1)(b-1) + k_{\Gamma} - nm(n-1)}{\lambda_2 - \lambda_1 + n}$.
    Moreover,
    \begin{equation}\label{eqn:trace}
    \begin{aligned}
        k_\Gamma^2+m(n-1)(\lambda_2-\lambda_1-n)^2
           +x(\lambda_2-\lambda_1)^2+yn^2=bk_\Gamma.
    \end{aligned}
    \end{equation}

By \eqref{eqn:specbtb}, the matrix $B^{ 
  {\mathpalette\@transpose{}} 
}B$ has the spectrum $[rk]^1,[r-\lambda_1]^{m(n-1)},[0]^{b-m(n-1)-1}$.

Multiplying \eqref{eqn:aux-mixed} on the left by $B^ 
  {\mathpalette\@transpose{}} 
$ and taking transposes, we obtain $A(\Gamma)B^{ 
  {\mathpalette\@transpose{}} 
}B = (\lambda_2 - \lambda_1 - n)B^{ 
  {\mathpalette\@transpose{}} 
}B + \frac{k^2}{v}(k_{\Gamma} + \lambda_1 - \lambda_2 + n) J$.
We consider the eigenvalue $r-\lambda_1$ of $B^{ 
  {\mathpalette\@transpose{}} 
}B$ which has multiplicity $m(n-1)$.
Any eigenvector in this eigenspace is orthogonal to $\mathbf{1}$. 
Hence, $A(\Gamma)$ has the eigenvalue $\lambda_2 - \lambda_1 - n$ on this eigenspace.

Now we use \eqref{eqn:aux-block} on the nullspace of $B^{ 
  {\mathpalette\@transpose{}} 
}B$.
This eigenspace (for eigenvalue $0$) is orthogonal to $\mathbf{1}$.
Hence, the eigenvalue of $A(\Gamma)$ on this eigenspace satisfies the quadratic equation $\theta^2 - (\lambda_2 - \lambda_1 - n)\theta - n(\lambda_2 - \lambda_1) = 0$.
Thus, the corresponding eigenvalues of $A(\Gamma)$ are $\lambda_2 - \lambda_1$ and $-n$.

Therefore, $A(\Gamma)$ has the spectrum $[k_\Gamma]^1,[\lambda_2-\lambda_1-n]^{m(n-1)},[\lambda_2-\lambda_1]^x,[-n]^y$ which implies $1 + m(n-1) + x + y = b$.
Furthermore, since $\operatorname{tr}{A(\Gamma)} = 0$, we have $k_{\Gamma} + m(n-1)(\lambda_2 - \lambda_1 - n) + x(\lambda_2 - \lambda_1) + y(-n) = 0$.
One can then solve to find $x = \frac{n(b-1) - k_{\Gamma} - m(\lambda_2 - \lambda_1)(n-1)}{\lambda_2 - \lambda_1 + n}$ and $y = \frac{(\lambda_2 - \lambda_1)(b-1) + k_{\Gamma} - nm(n-1)}{\lambda_2 - \lambda_1 + n}$, as required.
Finally, $\operatorname{tr}(A(\Gamma)^2)=bk_\Gamma$ because $\Gamma$ is $k_\Gamma$-regular.  
Evaluating this trace from the spectrum proves \eqref{eqn:trace}.

\label{lem:kernel-completion}
Let $B$ be a $v\times b$ $\{0,1\}$-matrix such that
\begin{align}
    \left(B-\frac1qJ\right)A(G_q)&=O,\label{eqn:family-centred-rows}\\
    \left(B-\frac1qJ\right)\left(B-\frac1qJ\right)^ 
  {\mathpalette\@transpose{}} 

       &=q^4I_v-q^2(I_m\otimes J_{q^2}).
        \label{eqn:target-centred-gram}
\end{align}
Then $B$ is the incidence matrix of a semiregular GDD $\mathcal D$ with parameters
\[
    (v,b;r,k;\lambda_1,\lambda_2;m,n)
    =\big(q^2(q^3+1),\ q^4(q+1);\ q^3(q+1),\ q(q^3+1);\
    q^3,\ q^2(q+1);\ q^3+1,\ q^2\big).
\]
Moreover, $G_q$ is an auxiliary graph for $\mathcal D$.

\label{thm:row4-muzychuk}
The matrix $M_4$ of Figure~\ref{fig:row4-matrix} is the incidence matrix of a semiregular GDD with parameters $(27,54;18,9;0,6;9,3)$, and $G$ is an auxiliary graph of this design.
Furthermore, $\left [ \begin{smallmatrix}
    J_{27}-I_9\otimes J_3&M_4\\M_4^ 
  {\mathpalette\@transpose{}} 
&A(G)
\end{smallmatrix}\right ]$ is the adjacency matrix of a biregular graph $\Gamma_{81}$ with degrees $42$ and $24$ and spectrum $\{[33]^1,[6]^{23},[-3]^{57}\}$.

Set $W=2B-J$ and $H=I_{15}\otimes J_4$.  
The row constraints give
\[
    WA(G)=4W,\qquad W\mathbf1=0,\qquad
    WW^ 
  {\mathpalette\@transpose{}} 
=128I_{60}-32H.
\]
For the indicator $\mathbf g$ of any group of four rows, the last identity gives $\|W^ 
  {\mathpalette\@transpose{}} 
\mathbf g\|^2=0$.  
Thus each group of sign rows sums to zero, and every column of $B$ contains two ones in each group.  
Consequently,
\begin{equation*}
\begin{gathered}
    BB^ 
  {\mathpalette\@transpose{}} 
=32I_{60}-8H+24J_{60},\\
    B\mathbf1=48\mathbf1,\qquad B^ 
  {\mathpalette\@transpose{}} 
\mathbf1=30\mathbf1,
    \qquad BA(G)=4B+8J.
\end{gathered}
\end{equation*}
These give the GDD parameters and semiregularity.  
The rank of $WW^ 
  {\mathpalette\@transpose{}} 
$ is $45$, so the rows of $W$ span
$E_4=\ker(A(G)-4I)$.  
The nonzero eigenvalues of $WW^ 
  {\mathpalette\@transpose{}} 
$ all equal $128$, so $W^ 
  {\mathpalette\@transpose{}} 
 W=128P_4$, where $P_4$ is the orthogonal projection onto $E_4$.  
Since $W^ 
  {\mathpalette\@transpose{}} 
\mathbf1=0$ and $B=(W+J)/2$, we have
\begin{equation}\label{eqn:hyp-column-gram}
    B^ 
  {\mathpalette\@transpose{}} 
 B=32P_4+15J=16I_{96}+4A(G)+14J_{96},
    \qquad P_4=\frac{16I+4A(G)-J}{32}.
\end{equation}
Together with \eqref{eqn:hyp-spectrum}, this gives $A(G)^2-4A(G)+B^ 
  {\mathpalette\@transpose{}} 
 B=32I+18J$.
The coefficient in \eqref{eqn:aux-block} is $((20+16-24)(20+4)+48\cdot30)/96=18$, so Theorem~\ref{thm:gdd-to-3ev} applies.
The quotient matrix $\left[\begin{smallmatrix}56&48\\30&20\end{smallmatrix}\right]$ has eigenvalues $80,-4$ and row sums $104,50$; the multiplicities follow from the order and trace of the full adjacency matrix.

\label{prop:family-coherent-type}
Let $q$ be a prime power.
Then the coherent closure $\mathcal W(\Gamma_q)$ has type $\left[\begin{smallmatrix}3&2\\2&5\end{smallmatrix}\right]$.
